8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives an owner's {@code customerCode}, the {@code <REGION>-<HASH8>} identity every
12	 * other owner-code-derived value is built from.
13	 *
14	 * <p>{@code REGION} is the region code derived from the owner's postcode
15	 * ({@link Localities#forPostcode(String)}), or {@code UNKNOWN} when the postcode is
16	 * absent or in no known range. {@code HASH8} is the first 8 upper-case hex characters
17	 * of the SHA-256 digest of the normalized telephone ({@link Telephones#toE164(String)})
18	 * concatenated with the last name. There are no sequence numbers: the identity is a
19	 * pure function of the owner's own fields.
20	 *
21	 * <p>Centralising the derivation here keeps {@link AssignCustomerCode} (which assigns
22	 * the code) and the {@code locality} mapping (which reads the region back off it) in
23	 * exact agreement.
24	 */
25	public final class CustomerCodes {
26	
27	    private CustomerCodes() {
28	    }
29	
30	    /** The {@code <REGION>-<HASH8>} customerCode for the given owner. */
31	    public static String forOwner(Owner owner) {
32	        return region(owner.getPostcode()) + "-" + hash8(owner);
33	    }
34	
35	    /**
36	     * The owner's locality: the {@code REGION} segment of its customerCode, so the
37	     * locality is derived from the region-and-hash identity. Falls back to the
38	     * postcode-derived region for owners without a customerCode.
39	     */
40	    public static String localityOf(Owner owner) {
41	        String code = owner.getCustomerCode();
42	        if (code != null) {
43	            int dash = code.indexOf('-');
44	            if (dash > 0) {
45	                return code.substring(0, dash);
46	            }
47	        }
48	        return region(owner.getPostcode());
49	    }
50	
51	    /** The region code derived from a postcode, or {@code UNKNOWN} when unresolved. */
52	    public static String region(String postcode) {
53	        String region = Localities.forPostcode(postcode);
54	        return region != null ? region : "UNKNOWN";
55	    }
56	
57	    /** First 8 upper-case hex chars of SHA-256 over (normalizedTelephone + lastName). */
58	    private static String hash8(Owner owner) {
59	        String telephone = Telephones.toE164(owner.getTelephone());
60	        String lastName = owner.getLastName();
